INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('ABD Adult', 'Enrollment', '6475', '6521', '+46', '+0.71%', 'Actual enrollment exceeded projection by 46 members. Consistent with statewide trend of increased ABD enrollment post-PHE. No PMPM variance detected.', 'RESOLVED — Variance within acceptable range (<1%). Noted for actuarial review in next budget cycle. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('ABD Dual', 'PMPM Cost', '$257.64', '$261.82', '+$4.18', '+1.62%', 'Actual PMPM exceeded budget by $4.18 (1.62%). Likely driven by increased utilization of dual-eligible services and higher pharmacy costs in Q4 SFY2022. Enrollment matched projection.', 'RESOLVED — Variance under 2.0% threshold. Flagged for monitoring in SFY2023 actuarial update. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('New Adult Childless', 'Enrollment', '35802', '36104', '+302', '+0.84%', 'Enrollment exceeded projection by 302 members. PHE continuous enrollment provisions prevented disenrollment of members who would otherwise have lost eligibility. Expected to normalize post-PHE unwinding.', 'RESOLVED — PHE-related variance documented. AHS and JFO notified. Projection to be revised in next budget cycle. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('New Adult w/Child', 'PMPM Cost', '$404.75', '$398.63', '($6.12)', '(1.51%)', 'Actual PMPM came in $6.12 below budget. Favorable variance attributable to lower-than-projected inpatient utilization and shift toward telehealth services with lower unit costs.', 'RESOLVED — Favorable variance. No corrective action required. Documented for budget performance report. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('ABD Child', 'PMPM Cost', '$1,068.01', '$1,092.47', '+$24.46', '+2.29%', 'PMPM exceeded budget by $24.46 (2.29%) — above the 2.0% threshold. ABD Child population has high acuity and is sensitive to utilization changes. Increased long-term care and behavioral health claims identified as primary drivers.', 'ESCALATED — Variance exceeds threshold. Referred to actuarial team for detailed claims analysis. Written response required from provider community. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('Underinsured Child', 'Enrollment', '530', '487', '(43)', '(8.11%)', 'Enrollment fell 43 members below projection (8.11% variance). Significant drop likely reflects transition of previously underinsured children to full Medicaid coverage under PHE continuous enrollment provisions.', 'RESOLVED — PHE enrollment shift confirmed with eligibility team. Members confirmed enrolled in General Child MEG. No financial exposure. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('Choices for Care', 'Enrollment', '4596', '4721', '+125', '+2.72%', 'Enrollment exceeded projection by 125 members (2.72%). Choices for Care is a high-cost HCBS waiver program. Additional enrollment has significant budget impact given $727.16 PMPM. Total annual cost impact approximately $1.09M above budget.', 'ESCALATED — High-impact variance. Budget amendment request submitted to Finance and Management. DAIL notified. Monitoring monthly. GP 9/15/22');
INSERT INTO findings_log (meg, variance_type, budget_figure, actual_figure, variance, variance_pct, finding_root_cause, resolution_status) VALUES ('General Adult', 'None', 'N/A', 'N/A', '$0.00', '0.00%', 'No material variance detected. Enrollment and PMPM both matched budget figures exactly. No action required.', 'CLOSED — Within threshold. No findings. GP 9/15/22');
